#!/usr/bin/env python3
"""Compute numeric ground truth for CSX-211_Q2."""

from __future__ import annotations

import html
import json
import re
from datetime import date
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-211_Q2"
EVENT_ID = "CSX-211"
TASK_TYPE = "numeric"


class VisibleTextParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"script", "style", "svg", "noscript"}:
            self.skip_depth += 1
        if self.skip_depth == 0 and tag in {"p", "h1", "h2", "h3", "li", "title"}:
            self.parts.append("\n")
        if self.skip_depth == 0:
            for key, value in attrs:
                if key in {"content", "alt", "title"} and value:
                    self.parts.append(value)

    def handle_endtag(self, tag: str) -> None:
        if tag in {"script", "style", "svg", "noscript"} and self.skip_depth:
            self.skip_depth -= 1
        if self.skip_depth == 0 and tag in {"p", "h1", "h2", "h3", "li"}:
            self.parts.append("\n")

    def handle_data(self, data: str) -> None:
        if self.skip_depth == 0:
            self.parts.append(data)

    def text(self) -> str:
        return re.sub(r"\s+", " ", html.unescape(" ".join(self.parts))).strip()


def load_json(package_dir: Path, relative_path: str) -> dict[str, Any]:
    return json.loads((package_dir / relative_path).read_text(encoding="utf-8"))


def read_visible_html(package_dir: Path, relative_path: str) -> str:
    parser = VisibleTextParser()
    parser.feed((package_dir / relative_path).read_text(encoding="utf-8", errors="ignore"))
    return parser.text()


def first_number(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1).replace(",", ""))


def first_month_day(pattern: str, text: str) -> tuple[int, int]:
    month_lookup = {
        "january": 1,
        "february": 2,
        "march": 3,
        "april": 4,
        "may": 5,
        "june": 6,
        "july": 7,
        "august": 8,
        "september": 9,
        "october": 10,
        "november": 11,
        "december": 12,
    }
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    month = month_lookup[match.group(1).lower()]
    return month, int(match.group(2))


def has_text(pattern: str, text: str) -> bool:
    return bool(re.search(pattern, text, flags=re.IGNORECASE))


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    event_path = "metadata/event.json"
    anchor_path = (
        "data/event_reports/"
        "event_reports_003_Locked_event_anchor_June_2023_Canadian_wildfire_smoke_over_New_York_City_and_the_U.S._Nort.json"
    )
    report_path = "data/event_reports/event_reports_001_Locked_anchor_report_NASA_Earth_Observatory.html"

    event = load_json(package_dir, event_path)
    anchor = load_json(package_dir, anchor_path)
    report_text = read_visible_html(package_dir, report_path)

    start_date = anchor["temporal_window"]["start_date"]
    end_date = anchor["temporal_window"]["end_date"]
    start = date.fromisoformat(start_date)
    end = date.fromisoformat(end_date)
    event_days = (end - start).days + 1

    low_top_km = first_number(r"near the surface up to about\s*([0-9.]+)\s*kilometers", report_text)
    mid_km = first_number(r"thinner layer at about\s*([0-9.]+)\s*kilometers", report_text)
    high_km = first_number(r"faint layer of smoke hovering at about\s*([0-9.]+)\s*kilometers", report_text)
    pm25_floor_ug_m3 = first_number(r"PM\s*2\.5.*?above\s*([0-9.]+)\s*micrograms", report_text)
    source_month, source_day = first_month_day(r"Alberta on\s+([A-Za-z]+)\s+([0-9]{1,2})", report_text)
    source_date = date(end.year, source_month, source_day)
    source_lag_days = (end - source_date).days

    evidence_flags = {
        "surface_air_degraded": has_text(r"degraded the quality of surface-level air", report_text),
        "near_surface_present": has_text(r"significant amount of smoke is present near the surface", report_text),
        "multilayer_present": has_text(r"multi-layered smoke plume", report_text),
        "old_high_layer": has_text(r"12 kilometers is a month old", report_text),
    }
    if not all(evidence_flags.values()):
        raise ValueError(f"Missing expected evidence flags: {evidence_flags}")

    near_surface_share = round(low_top_km / high_km, 3)
    high_to_low_ratio = round(high_km / low_top_km, 3)
    low_to_high_gap_km = round(high_km - low_top_km, 3)
    lag_to_window_ratio = round(source_lag_days / event_days, 3)

    layer_km = {
        "low_top": int(low_top_km),
        "mid": int(mid_km),
        "high": int(high_km),
    }
    consistency_proof = (
        "The low smoke layer reaches from near the surface to about 3 km, so it is the surface-coupled exposure layer; "
        "the 12 km layer is four times that height and traces back 34 days to Alberta, so it is old high-layer transport context."
    )
    primary_gt = {
        "event_window": {"start_date": start_date, "end_date": end_date, "duration_days": event_days},
        "layer_km": layer_km,
        "near_surface_share": near_surface_share,
        "high_to_low_ratio": high_to_low_ratio,
        "pm25_floor_ug_m3": int(pm25_floor_ug_m3),
        "high_layer_lag_days": source_lag_days,
        "consistency_proof": consistency_proof,
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": TASK_TYPE,
        "target_family": "vertical_smoke_exposure_ledger",
        "evaluation_mode": "deterministic_numeric_json",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "judge_anchors": {
            "answer": near_surface_share,
            "event_days": event_days,
            "pm25_floor": int(pm25_floor_ug_m3),
            "high_lag_days": source_lag_days,
            "label": "surface_coupled_low_layer_with_old_high_layer",
            "tolerance": 0.001,
            "units": "share",
        },
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": {
                "start_date": start_date,
                "end_date": end_date,
                "duration_days": event_days,
            },
            "layer_km": layer_km,
            "near_surface_share": near_surface_share,
            "high_to_low_ratio": high_to_low_ratio,
            "low_to_high_gap_km": low_to_high_gap_km,
            "pm25_floor_ug_m3": int(pm25_floor_ug_m3),
            "high_layer_source_date": source_date.isoformat(),
            "high_layer_lag_days": source_lag_days,
            "lag_to_window_ratio": lag_to_window_ratio,
            "evidence_flags": evidence_flags,
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Event window reconstruction",
                    "points": 3,
                    "description": "Reports 2023-06-06 to 2023-06-08 as a 3-day window.",
                    "partial_credit": "Award 1-2 points for correct dates with an arithmetic slip or correct duration with incomplete dates.",
                },
                {
                    "name": "Layer-height extraction",
                    "points": 4,
                    "description": "Extracts low-top, middle, and high smoke layers as 3, 6, and 12 km.",
                    "partial_credit": "Award partial credit for each correctly reported height with km units.",
                },
                {
                    "name": "Vertical fraction arithmetic",
                    "points": 4,
                    "description": "Computes near-surface share as 3/12 = 0.25 and high-to-low ratio as 12/3 = 4.0.",
                    "partial_credit": "Award 1-3 points for a correct setup with one missing or rounded derived value.",
                },
                {
                    "name": "Surface-severity anchor",
                    "points": 3,
                    "description": "Uses the report's PM2.5 lower bound above 400 micrograms per cubic meter as a surface-air anchor.",
                    "partial_credit": "Award 1-2 points for recognizing the surface-air evidence without the numeric lower bound.",
                },
                {
                    "name": "Old high-layer lag",
                    "points": 3,
                    "description": "Computes the Alberta May 5 to 2023-06-08 lag as 34 days and ties it to the 12 km layer.",
                    "partial_credit": "Award 1-2 points for correct source date or approximate month-old interpretation without exact lag.",
                },
                {
                    "name": "Compact consistency proof",
                    "points": 3,
                    "description": "States that the low layer is the surface-coupled exposure layer while the high layer is older transport context using only computed layer and PM2.5 fields.",
                    "partial_credit": "Award 1-2 points for a concise proof missing one of the two contrasts.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                event_path,
                anchor_path,
                report_path,
            ],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True, ensure_ascii=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
